<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>AvrupaPazari | Yapım Aşamasında</title>
<style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Arial,sans-serif}body{min-height:100vh;display:grid;place-items:center;overflow:hidden;padding:24px;background:radial-gradient(circle at 50% 0,#fff 0,transparent 48%),linear-gradient(135deg,#effdf3,#dff9e8 52%,#f8fffa);color:#17352a}.glow{position:fixed;border-radius:50%;pointer-events:none;filter:blur(3px)}.g1{width:360px;height:360px;left:-160px;top:-160px;background:radial-gradient(circle,rgba(74,222,128,.32),transparent 68%);animation:drift 9s ease-in-out infinite}.g2{width:320px;height:320px;right:-150px;bottom:-150px;background:radial-gradient(circle,rgba(16,185,129,.22),transparent 68%);animation:drift 11s ease-in-out -3s infinite reverse}.card{position:relative;width:min(680px,100%);padding:44px 34px 38px;text-align:center;background:rgba(255,255,255,.93);border:1px solid rgba(22,163,74,.2);border-radius:34px;box-shadow:0 28px 90px rgba(6,95,70,.15),0 5px 18px rgba(6,95,70,.06);animation:enter .8s ease both}.card:before{content:"";position:absolute;inset:10px;border:1px solid rgba(22,163,74,.08);border-radius:27px;pointer-events:none}.orbit{position:relative;width:132px;height:132px;margin:0 auto 26px;border:1px solid rgba(22,163,74,.22);border-radius:50%;display:grid;place-items:center;animation:spin 14s linear infinite}.orbit:before,.orbit:after{content:"";position:absolute;border-radius:50%;background:#16a34a;box-shadow:0 0 0 7px rgba(22,163,74,.1),0 0 20px rgba(22,163,74,.5)}.orbit:before{width:12px;height:12px;top:10px;left:18px}.orbit:after{width:8px;height:8px;right:10px;bottom:20px;background:#34d399}.house{width:82px;height:82px;display:grid;place-items:center;border-radius:26px;background:linear-gradient(145deg,#dcfce7,#bbf7d0);color:#16a34a;box-shadow:0 14px 30px rgba(22,163,74,.16);animation:float 3.5s ease-in-out infinite}.house svg{width:46px;height:46px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.brand{margin:0 0 11px;color:#16a34a;font-size:12px;font-weight:800;letter-spacing:.22em;text-transform:uppercase}h1{margin:0 0 18px;color:#065f46;font-size:clamp(34px,6vw,52px);letter-spacing:-.05em;line-height:1.05}.langs{display:flex;justify-content:center;gap:8px;margin-bottom:21px}.langs span{padding:6px 10px;border:1px solid #c9efd5;border-radius:99px;background:#f2fff5;color:#168044;font-size:11px;font-weight:800}.messages{display:grid;gap:9px;max-width:510px;margin:auto;text-align:left}.msg{display:flex;gap:12px;align-items:flex-start;padding:12px 14px;border:1px solid #e4f3e8;border-radius:15px;background:#f8fffa;animation:show .7s ease both}.msg:nth-child(2){animation-delay:.12s}.msg:nth-child(3){animation-delay:.24s}.tag{width:34px;height:25px;flex:0 0 34px;display:grid;place-items:center;border-radius:7px;background:#dcfce7;color:#168044;font-size:11px;font-weight:800}.msg strong{display:block;margin-bottom:3px;color:#065f46;font-size:13px}.msg p{margin:0;color:#688178;font-size:13px;line-height:1.45}.bar{height:5px;width:min(300px,80%);margin:27px auto 0;overflow:hidden;border-radius:9px;background:#dcfce7}.bar i{display:block;width:38%;height:100%;border-radius:9px;background:linear-gradient(90deg,#16a34a,#6ee7b7);animation:load 2.4s ease-in-out infinite}.foot{margin:15px 0 0;color:#8aa197;font-size:11px}@keyframes enter{from{opacity:0;transform:translateY(18px) scale(.97)}to{opacity:1;transform:none}}@keyframes show{from{opacity:0;transform:translateX(-10px)}to{opacity:1;transform:none}}@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes drift{0%,100%{transform:translate(0)}50%{transform:translate(20px,14px)}}@keyframes load{0%{transform:translateX(-180%)}55%,100%{transform:translateX(360%)}}@media(max-width:560px){body{overflow:auto;padding:14px}.card{padding:34px 17px 28px;border-radius:27px}.orbit{width:110px;height:110px}.house{width:70px;height:70px;border-radius:21px}.house svg{width:39px;height:39px}.msg p{font-size:12px}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}
</style>
</head>
<body>
<div class="glow g1"></div><div class="glow g2"></div>
<main class="card">
<div class="orbit"><div class="house"><svg viewBox="0 0 24 24"><path d="m3 11 9-8 9 8"/><path d="M5 10v10h14V10"/><path d="M9 20v-6h6v6"/><path d="M8 6h.01M16 6h.01"/></svg></div></div>
<p class="brand">AvrupaPazari</p><h1>Yapım Aşamasında</h1>
<div class="langs"><span>TR</span><span>NL</span><span>EN</span></div>
<section class="messages"><div class="msg"><span class="tag">TR</span><div><strong>Türkçe</strong><p>Sitemizi daha güzel bir deneyim için yeniliyoruz. Çok yakında tekrar buradayız.</p></div></div><div class="msg"><span class="tag">NL</span><div><strong>Nederlands</strong><p>We vernieuwen onze website voor een betere ervaring. We zijn binnenkort weer online.</p></div></div><div class="msg"><span class="tag">EN</span><div><strong>English</strong><p>We are updating our website for a better experience. We will be back online soon.</p></div></div></section>
<div class="bar"><i></i></div><p class="foot">Güncellemeler devam ediyor · Updates in progress · Updates worden uitgevoerd</p>
</main>
</body></html>
